from minidb.types import (
    And,
    ColumnRef,
    Comparison,
    Expr,
    IsNull,
    Literal,
    Not,
    Or,
    Row,
    Schema,
    TypeMismatchError,
    Value,
    sql_type_name,
)

__all__ = [
    "evaluate",
    "compare",
    "logical_not",
    "logical_and",
    "logical_or",
    "where_matches",
]

def evaluate(expr: Expr, row: Row, schema: Schema) -> Value:
    if isinstance(expr, Literal):
        return expr.value
    elif isinstance(expr, ColumnRef):
        return row[schema.index_of(expr.name)]
    elif isinstance(expr, Comparison):
        left_value = evaluate(expr.left, row, schema)
        right_value = evaluate(expr.right, row, schema)
        return compare(expr.op, left_value, right_value)
    elif isinstance(expr, IsNull):
        operand_value = evaluate(expr.operand, row, schema)
        return operand_value is None if not expr.negated else operand_value is not None
    elif isinstance(expr, Not):
        operand_value = evaluate(expr.operand, row, schema)
        return logical_not(operand_value)
    elif isinstance(expr, And):
        left_value = evaluate(expr.left, row, schema)
        right_value = evaluate(expr.right, row, schema)
        return logical_and(left_value, right_value)
    elif isinstance(expr, Or):
        left_value = evaluate(expr.left, row, schema)
        right_value = evaluate(expr.right, row, schema)
        return logical_or(left_value, right_value)
    else:
        raise ValueError("Unsupported expression type")

def compare(op: str, left: Value, right: Value) -> Value:
    if left is None or right is None:
        return None
    if sql_type_name(left) != sql_type_name(right):
        raise TypeMismatchError(f"Cannot compare {sql_type_name(left)} with {sql_type_name(right)}")
    if op == "==":
        return left == right
    elif op == "<>":
        return left != right
    elif op == \<":
        return left < right
    elif op == "<=":
        return left <= right
    elif op == ">":
        return left > right
    elif op == ">=":
        return left >= right
    else:
        raise ValueError(f"Unsupported comparison operator: {op}")

def logical_not(value: Value) -> Value:
    if value is True:
        return False
    elif value is False:
        return True
    elif value is None:
        return None
    else:
        raise TypeMismatchError(f"Expected boolean or None, got {type(value).__name__}")

def logical_and(left: Value, right: Value) -> Value:
    if left is False or right is False:
        return False
    elif left is None or right is None:
        return None
    elif left is True and right is True:
        return True
    else:
        raise TypeMismatchError(f"Expected boolean or None, got {type(left).__name__} and {type(right).__name__}")

def logical_or(left: Value, right: Value) -> Value:
    if left is True or right is True:
        return True
    elif left is None or right is None:
        return None
    elif left is False and right is False:
        return False
    else:
        raise TypeMismatchError(f"Expected boolean or None, got {type(left).__name__} and {type(right).__name__}")

def where_matches(expr: Expr, row: Row, schema: Schema) -> bool:
    result = evaluate(expr, row, schema)
    if result is True:
        return True
    elif result is False or result is None:
        return False
    else:
        raise TypeMismatchError(f"Expected boolean or None, got {type(result).__name__}")

